  runtime: 'Node-RED 4.1 + Python 3.11 (uv)',
  backend: 'node-red'
};
return msg;

const fs = global.get('fs');
const path = global.get('path');
const root = global.get('projectRoot') || '.';
const envObj = global.get('env') || {};
const dataDir = path.join(root, 'data');

// 1. Read Jobs
let jobs = [];
const jobsPath = path.join(dataDir, 'jobs.json');
try {
  if (fs.existsSync(jobsPath)) {
    jobs = JSON.parse(fs.readFileSync(jobsPath, 'utf8'));
  }
} catch (e) { jobs = []; }
flow.set('jobs', jobs);

// 2. Read Planner Slots
let slots = [];
const plannerPath = path.join(dataDir, 'planner.json');
try {
  if (fs.existsSync(plannerPath)) {
    const pData = JSON.parse(fs.readFileSync(plannerPath, 'utf8'));
    slots = pData.slots || [];
  }
} catch (e) { slots = []; }

if (!slots || slots.length === 0) {
  slots = [];
  const times = [
    ['09:00', 'Dimineață (Tech News & Hooks)'],
    ['12:00', 'Prânz (Viral Story / Poveste AI)'],
    ['18:00', 'Seară (Deep Dive & Curiozități)'],
    ['21:00', 'Noapte (Suno Music / Chill Vibe)']
  ];
  for (let d = 0; d < 7; d++) {
    const date = new Date(Date.now() + d * 86400000);
    const ds = date.toISOString().slice(0, 10);
    const day = date.toLocaleDateString('ro-RO', { weekday: 'long' });
    for (const [time, label] of times) {
      slots.push({
        id: `slot_${ds}_${time.replace(':', '')}`,
        date: ds,
        dayName: day.charAt(0).toUpperCase() + day.slice(1),
        time,
        label,
        status: 'empty',
        item: null
      });
    }
  }
  try {
    fs.mkdirSync(dataDir, { recursive: true });
    fs.writeFileSync(plannerPath, JSON.stringify({ slots, lastUpdated: new Date().toISOString() }, null, 2), 'utf8');
  } catch (e) {}
}
flow.set('slots', slots);

msg.statusCode = 200;
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
  jobs,
  planner: { slots, lastUpdated: new Date().toISOString() },
  integrations: {
    nodeRed: 'connected',
    python: 'connected',
    ffmpeg: 'local',
    videoWorker: global.get('videoWorkerStatus') || 'offline',
    youtube: envObj.YOUTUBE_CLIENT_ID ? 'configured' : 'not_configured',
    telegram: envObj.TELEGRAM_BOT_TOKEN ? 'configured' : 'not_configured'
  }
};
return msg;

const fs = global.get('fs');
const path = global.get('path');
const root = global.get('projectRoot') || '.';
const dataDir = path.join(root, 'data');
const jobsPath = path.join(dataDir, 'jobs.json');

const input = msg.payload || {};
const topic = String(input.topic || '').trim();
msg.headers = { 'content-type': 'application/json' };

if (topic.length < 5) {
  msg.statusCode = 400;
  msg.payload = { error: 'Subiectul trebuie să aibă minimum 5 caractere.' };
  return msg;
}

const id = `job-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
const job = {
  id,
  topic,
  title: String(input.title || topic).trim(),
  format: input.format === '16:9' ? '16:9' : '9:16',
  durationSeconds: Math.min(180, Math.max(8, Number(input.durationSeconds) || 30)),
  privacyStatus: ['private', 'unlisted', 'public'].includes(input.privacyStatus) ? input.privacyStatus : 'private',
  status: 'draft',
  prompt: String(input.prompt || `Cinematic vertical 9:16 video about ${topic}, dynamic camera, strong visual hook, realistic lighting.`),
  audioUrl: null,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString()
};

let jobs = [];
try {
  if (fs.existsSync(jobsPath)) {
    jobs = JSON.parse(fs.readFileSync(jobsPath, 'utf8'));
  }
} catch (e) { jobs = []; }

jobs.unshift(job);

try {
  fs.mkdirSync(dataDir, { recursive: true });
  fs.writeFileSync(jobsPath, JSON.stringify(jobs, null, 2), 'utf8');
} catch (e) {}

flow.set('jobs', jobs);
msg.statusCode = 201;
msg.payload = job;
node.status({ fill: 'green', shape: 'dot', text: `${jobs.length} proiecte` });
return msg;

const fs = global.get('fs');
const path = global.get('path');
const root = global.get('projectRoot') || '.';
const jobsPath = path.join(root, 'data', 'jobs.json');

const allowed = ['draft', 'awaiting_assets', 'ready', 'rendering', 'review', 'approved', 'published', 'failed'];
let jobs = [];
try {
  if (fs.existsSync(jobsPath)) {
    jobs = JSON.parse(fs.readFileSync(jobsPath, 'utf8'));
  }
} catch (e) { jobs = []; }

const jobId = msg.req.params.id;
const job = jobs.find(j => j.id === jobId);
msg.headers = { 'content-type': 'application/json' };

if (!job) {
  msg.statusCode = 404;
  msg.payload = { error: 'Job inexistent.' };
  return msg;
}

if (!allowed.includes(msg.payload.status)) {
  msg.statusCode = 400;
  msg.payload = { error: 'Status invalid.' };
  return msg;
}

job.status = msg.payload.status;
job.updatedAt = new Date().toISOString();

try {
  fs.writeFileSync(jobsPath, JSON.stringify(jobs, null, 2), 'utf8');
} catch (e) {}

flow.set('jobs', jobs);
msg.statusCode = 200;
msg.payload = job;
return msg;

